// Generated by shared/catalog/types.mjs from shared/catalog (schemas and ids). Don't edit:
// run `npm run catalog` in frontend/ (npm run build does it too).

/** A catalog id: lower case, digits and underscores, starting with a letter. */
export type Id = string;

/** The game's one rarity palette (frontend collection/rarity.ts, backend profiles.py RARITIES). */
export type Rarity = "common" | "uncommon" | "rare" | "legendary";

/** A biome of frontend game/world/biomes (a test checks this list against BIOMES). */
export type BiomeId = "skyIsles" | "verdant" | "glacier" | "archipelago" | "lagoon" | "twilight" | "ember" | "aurora" | "reef";

/** Every stat the stat system (F2) knows. wisdom = skill XP bonus in percent. */
export type StatId = "light" | "ward" | "might" | "crit" | "critPower" | "haste" | "focus" | "swiftness" | "harvestFortune" | "timberFortune" | "oreFortune" | "angling" | "luck" | "wisdom";

/** Some stats and their amounts. */
export type StatBlock = { readonly [K in StatId]?: number };

/** A number of one item. */
export interface Amount {
  readonly item: Id;
  readonly count: number;
}

/** [min, max], both included. */
export type CountRange = readonly [number, number];

/** Skill id -> the level needed. */
export type SkillLevels = { readonly [K in Id]?: number };

/** [x, z] in metres on the Reaches' map, Lanternhaven at [0, 0]. */
export type Point = readonly [number, number];

export type ItemKind = "currency" | "material" | "tool" | "weapon" | "mantle" | "charm" | "rune" | "tea" | "seed" | "furniture" | "book" | "gem" | "stone" | "essence";

/** Where gear is worn (plan A6). Cosmetics stay the look; gear is a stat item. */
export type GearSlot = "weapon" | "mantle" | "circlet" | "boots" | "charm";

/** Kinds of resource node a tool breaks (plan R2). */
export type NodeKind = "crop" | "fruit" | "tree" | "vein" | "fish" | "herb" | "feather";

export interface Item {
  readonly id: Id;
  readonly name: string;
  readonly kind: ItemKind;
  readonly rarity: Rarity;
  /** Most in one bag slot; 1 for tools and gear. */
  readonly stack: number;
  /** A model builder in game/reaches/models: group/name. */
  readonly model: string;
  /** "auto": rendered from the model at build time (plan F8). */
  readonly icon: string;
  /** Coins an NPC pays for one. */
  readonly sell: number;
  /** Where it is found, if one place. */
  readonly region?: Id;
  readonly lore: string;
  readonly slot?: GearSlot;
  readonly stats?: StatBlock;
  /** A gear ability (plan A6), e.g. gale_lunge. */
  readonly ability?: Id;
  readonly requires?: SkillLevels;
  /** Tools: the skill they serve. */
  readonly skill?: Id;
  /** Tools: bonus yield, in percent. */
  readonly fortune?: number;
  /** Tools: gathering speed multiplier. */
  readonly speed?: number;
  /** Tools: the node kinds they gather. */
  readonly breaks?: readonly NodeKind[];
}

export interface ItemsFile {
  readonly items: readonly Item[];
}

/** Where a recipe is made (plan F10). */
export type Station = "workbench" | "loom" | "kettle" | "smith" | "rune_pedestal";

/** Either a skill level (skill + level) or a collection tier (collection + tier). */
export interface RecipeUnlock {
  readonly skill?: Id;
  readonly level?: number;
  readonly collection?: Id;
  readonly tier?: number;
}

export interface Recipe {
  readonly id: Id;
  readonly station: Station;
  readonly inputs: readonly Amount[];
  readonly output: Amount;
  /** Seconds; timed crafts finish while away (0 = at once). */
  readonly time: number;
  readonly unlock?: RecipeUnlock;
}

export interface RecipesFile {
  readonly recipes: readonly Recipe[];
}

export type UnlockKind = "recipe" | "region" | "item";

export interface SkillUnlock {
  readonly level: number;
  readonly kind: UnlockKind;
  readonly id: Id;
}

export interface Skill {
  readonly id: Id;
  readonly name: string;
  /** The skill's colour (emblem, toast). */
  readonly color: string;
  readonly curve: Id;
  readonly maxLevel: number;
  /** Stats gained at every level. */
  readonly perLevel: StatBlock;
  readonly unlocks: readonly SkillUnlock[];
}

export interface SkillsFile {
  /** The part of every skill XP that is also Wind Rank XP (the profile's level), plan F4. */
  readonly windRankShare: number;
  /** Curve id -> XP needed for each level after the first (index 0: level 1 -> 2). */
  readonly curves: { readonly [K in Id]?: readonly number[] };
  readonly skills: readonly Skill[];
}

export interface Drop {
  readonly item: Id;
  readonly count: CountRange;
}

export interface WeightedDrop {
  readonly item: Id;
  /** Relative chance among the table's entries; must be > 0. */
  readonly weight: number;
  readonly count: CountRange;
}

export interface RareDrop {
  readonly item: Id;
  /** Rolled once per opening, on top of the entries. */
  readonly chance: number;
  /** After this many misses in a row the next one is certain (0 or absent: no pity). */
  readonly pity?: number;
  readonly count: CountRange;
}

export interface LootTable {
  readonly id: Id;
  /** Picks from entries, by weight, with replacement. */
  readonly rolls: number;
  readonly guaranteed?: readonly Drop[];
  readonly entries: readonly WeightedDrop[];
  readonly rare?: readonly RareDrop[];
}

export interface LootFile {
  readonly tables: readonly LootTable[];
}

/** The AI behaviours of plan A2. */
export type Behaviour = "drift" | "orbit" | "chase" | "strafe" | "guard" | "dive" | "swarm";

export interface Telegraph {
  /** What the player sees and hears. */
  readonly cue: string;
  /** Warning before damage; at least 0.6 s (plan A4). */
  readonly seconds: number;
}

/** A Murk family (plan A4). Murk are purified, never killed (ground rule 5). */
export interface Enemy {
  readonly id: Id;
  readonly name: string;
  readonly behaviour: Behaviour;
  /** Its Light (health) before it is purified. */
  readonly light: number;
  /** Light a hit takes from the pilot. */
  readonly might: number;
  /** Damage it shrugs off per hit. */
  readonly ward: number;
  /** Cruising speed, m/s. */
  readonly speed: number;
  readonly telegraph: Telegraph;
  /** The happy spirit it becomes when purified. */
  readonly freed: string;
  /** A loot.json table rolled on purification. */
  readonly loot: Id;
  readonly model: string;
  readonly lore: string;
}

export interface EnemiesFile {
  readonly enemies: readonly Enemy[];
}

export type Layer = "surface" | "deep";

/** How regions meet (game/reaches/regions.ts, backend/regions.py): metres over which two regions blend, and the hub into them; how far, and over what distance, the borders wander. */
export interface Borders {
  readonly band: number;
  readonly hubBand: number;
  readonly warp: number;
  readonly warpScale: number;
}

/** Lanternhaven, a hand-authored set piece at the centre (plan R3). */
export interface Hub {
  readonly id: Id;
  readonly name: string;
  readonly center: Point;
  readonly radius: number;
}

export interface Region {
  readonly id: Id;
  readonly name: string;
  readonly biome: BiomeId;
  readonly skills: readonly Id[];
  /** Signature places. */
  readonly places: readonly string[];
  readonly center: Point;
  readonly radius: number;
  /** deep: under other regions (the Hollow Deeps). */
  readonly layer: Layer;
  readonly note?: string;
}

export interface RegionsFile {
  /** Metres from the hub to the edge of the Reaches. */
  readonly worldRadius: number;
  /** The region map's cell size in metres (plan R1). */
  readonly cell: number;
  /** The world seed: the same Reaches for everyone (plan R1). */
  readonly seed: number;
  readonly borders: Borders;
  readonly hub: Hub;
  readonly regions: readonly Region[];
}

export interface Choice {
  readonly text: string;
  /** A line of the same NPC. */
  readonly next?: Id;
  /** Offers this quest. */
  readonly quest?: Id;
}

export interface Line {
  readonly id: Id;
  readonly text: string;
  readonly choices?: readonly Choice[];
}

export interface Npc {
  readonly id: Id;
  readonly name: string;
  readonly role: string;
  /** A region or the hub. */
  readonly region: Id;
  readonly station?: Station;
  /** Babble pitch, 1 = neutral. */
  readonly voice: number;
  /** What they do while nobody talks to them. */
  readonly idle: string;
  readonly lines: readonly Line[];
}

export interface NpcsFile {
  readonly npcs: readonly Npc[];
}

export type QuestKind = "fetch" | "gather" | "deliver" | "explore" | "catch";

/** fetch/gather/catch: item + count; deliver: item + count + npc; explore: region. */
export interface QuestGoal {
  readonly item?: Id;
  readonly count?: number;
  readonly npc?: Id;
  readonly region?: Id;
}

export interface QuestRewards {
  readonly coins?: number;
  readonly items?: readonly Amount[];
  /** Skill id -> XP. */
  readonly xp?: { readonly [K in Id]?: number };
}

export interface Quest {
  readonly id: Id;
  readonly name: string;
  readonly giver: Id;
  readonly kind: QuestKind;
  readonly goal: QuestGoal;
  readonly rewards: QuestRewards;
  /** Quests to finish first. */
  readonly requires?: readonly Id[];
  /** Offered on the Lantern Plaza's notice board. */
  readonly board?: boolean;
  readonly text: string;
}

export interface QuestsFile {
  readonly quests: readonly Quest[];
}

/** How the value reads: a plain number or a percentage. */
export type StatUnit = "" | "%";

export type StatGroup = "combat" | "gathering" | "general";

export interface StatInfo {
  readonly id: StatId;
  readonly name: string;
  readonly group: StatGroup;
  /** Every pilot's value before any source. */
  readonly base: number;
  /** The most it can reach (absent: no cap). Stats never go below 0. */
  readonly cap?: number;
  readonly unit: StatUnit;
  readonly description: string;
}

/** Runs only (rule 6): swiftness raises top speed by perPoint each, never more than cap (fractions: 0.08 = +8%). */
export interface SwiftnessFlight {
  readonly perPoint: number;
  readonly cap: number;
}

export interface StatsFile {
  /** Every stat once, in display order. */
  readonly stats: readonly StatInfo[];
  readonly swiftnessFlight: SwiftnessFlight;
}

